registerRefData('nsw-cond-n-201',{"id":201,"pan":null,"ref":"DA/2371/2023","address":"12-14 Jennings Road Wyong 2259","description":"Multi Dwelling Development","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-10-15","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-363!20251015T031706.781 GMT","sha256":"0b9a2a896a5e47ef625b26573629ea608afec22e200bbabef62f858af979faf5","pages":27,"layout":"numbered","n":15,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/201.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/multi-dwelling-development-2","lga":"CENTRAL COAST","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-363 - Central Coast - DA/2371/2023","stage":"general","stage_basis":"heading","page":5},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Demolition of 2 dwellings, tree and vegetation removal. Construction of 16\nx 2 bedroom and 4 x 3-bedroom affordable houses, 12 car spaces, waste\nroom (21 bins), 70 square metres communal open space.","stage":"general","stage_basis":"heading","page":5},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 12-14 Jennings Road, Wyong 2259","text":"","stage":"general","stage_basis":"heading","page":5},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Hume Community Housing Association Company Limited","text":"","stage":"general","stage_basis":"heading","page":5},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Private infrastructure and community facilities over $5 million","stage":"general","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Sustainable Buildings) 2022\no Central Coast Local Environmental Plan 2022\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Central Coast Development Control Plan 2022\n• Planning agreements: Nil\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021 - section 61(1) - demolition requirements\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 30 September 2025\n• List any clause 4.6 variation requests here\n• List any Council memo or supplementary report received: 1 October\n2025, 2 October 2025 and 8 October 2025\n• Written submissions during public exhibition: 0\n• Total number of unique submissions received by way of objection: 0","stage":"general","stage_basis":"heading","page":5},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Initial Briefing: 22 July 2025\no Panel members: Alison McCabe (Chair), Roberta Ryan, Tony\nMcNamara, Rachel Stanton\no Applicant representatives: Dan Lincoln, Wei Ji, Bryce Luke,\nWilliam Phelps, Susan Tabikh, Penny Smith\no Council assessment staff: Emma Brown, Tania Halbert, Salli\nPendergast\no Department: Leanne Harris, Holly McCann\n• Site inspection:\no Rachel Stanton: 19 July 2025\n• Final briefing to discuss Council’s recommendation: 7 October 2025\no Panel members: Alison McCabe (Chair), Roberta Ryan, Rachel\nStanton\no Council assessment staff: Emma Brown. Ilena Wilson, Lara Davis,\nSalli Pendergast, Tania Halbert\no Applicant representatives: Dan Lincoln, Bryce Luke, Josh\nLyons, William Phelps, Penny Smith\no Department: Leanne Harris, Holly McCann\no Department: Vibha Meghnad and Stcey McMasters (observing)","stage":"general","stage_basis":"heading","page":5},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":6},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report","text":"PROPOSED CONDITIONS\n1.1 Approved Plans and Supporting Documentation\nDevelopment must be carried out in accordance with the following approved plans and\nsupporting documentation (stamped by Council), except where the conditions of this\nconsent expressly require otherwise.\nPlan No. Revision\nNo. Plan Title Drawn\nBy Dated\nDRAWING LIST\nA001 COVER SHEET / LOCATION\nPLAN NTS\nA002 SITE ANALYSIS 1\nA003 STREETSCAPE ANALYSIS\nA101 DEMOLITION PLAN\nA102 SITE PLAN\nA103 ROOF PLAN\nA104 SITE SECTIONS /\nELEVATIONS 1:200\n5 Architectural\nPlans\nMcIntosh\n& Phelps\n18 August\n2025\nSCHEDULE 2\n1.PARAMETERS OF THIS CONSENT\nA201 FLOOR PLANS 01-04 & 08-","stage":"general","stage_basis":"heading","page":6},{"label":"13","code":null,"number":"13","title":"A202 FLOOR PLANS 05-07 & 14-","text":"","stage":"general","stage_basis":"heading","page":8},{"label":"16","code":null,"number":"16","title":"A203 FLOOR PLANS 17-20","text":"A204 FLOOR PLAN - LOWER\nGROUND\nA301 ELEVATIONS 01-16\nA302 ELEVATIONS 01-16\nA303 ELEVATIONS 01-16\nA304 ELEVATIONS 01-16\nA305 ELEVATIONS 17-20\nA401 STREET VIEW NTS\nA402 AERIAL VIEW NTS\nA403 AERIAL VIEW NTS\nA501 EXTERNAL FINISHES\nSELECTIONS NTS\nA601 SHADOW DIAGRAMS - 21\nJUNE - 0900\nA602 SHADOW DIAGRAMS - 21\nJUNE - 1200\nA603 SHADOW DIAGRAMS - 21\nJUNE - 1500\nA604 VIEW FROM SUN NTS\nA605 VIEW FROM SUN NTS\nA606 SOLAR ACCESS SUMMARY\nTABLE NTS\nA701 LANDSCAPE PLAN\nA702 PLANTING SCHEDULE NTS\nA703 LANDSCAPE AREAS\nCIVIL","stage":"general","stage_basis":"heading","page":8},{"label":"1","code":null,"number":"1","title":"LOCATION PLAN &","text":"DRAWING SCHEDULE NTS\n101 EROSION & SEDIMENT\nCONTROL PLAN\n111 EROSION & SEDIMENT\nCONTROL DETAILS AS SHOWN\n201 BULK EARTHWORK PLAN\n301 STORMWATER PLAN\n401 SITEWORK PLAN\n461 LONGITUDINAL SECTION -\nMC00 AS SHOWN\n601 OSD DETAILS AS SHOWN\nHYDRAULICS\nH000 COVERSHEET, LEGENDS,\nNOTES AND DRAWING LIST NTS\nH001 HYDRAULIC\nSPECIFICATION NTS\nH002 SITE PLAN\nSURVEY\n1/1 DETAIL SURVEY PLAN OF\nLOT 1 DP 1230068","stage":"general","stage_basis":"heading","page":8},{"label":"1","code":null,"number":"1","title":"LOCATION PLAN & DRAWING","text":"SCHEDULE\n101 SOIL WATER AND\nMANAGEMENT PLAN\n111 SOIL & WATER\nMANAGEMENT NOTES &\nDETAILS SHEET 1 OF 2\n112 SOIL & WATER\nMANAGEMENT NOTES &\nDETAILS SHEET 2 OF 2\n201 BULK EARTHWORK PLAN\n301 STORMWATER PLAN\n401 SITEWORK PLAN\n461 LONGITUDINAL SECTION -\nMC00\n602 OSD DETAILS\n701 VEHICLE CLEARANCES -\nSHEET 1 OF 3\n702 VEHICLE CLEARANCES -\nSHEET 2 OF 3\n703 VEHICLE CLEARANCES -\nSHEET 3 OF 3\n801 VERGE SECTION","stage":"general","stage_basis":"heading","page":9},{"label":"3","code":null,"number":"3","title":"Civil","text":"Engineering\nPlans and\nTonkin\n18 August\n2025\nH000-H002\nP4\nCivil\nEngineering\nHydraulic\nPlans\nCentric\n13 August\n2025\nDocument Title Version\nNo. Prepared by Dated\nOperational Waste Management Revision 1 Elephants Foot 27 March 2025\nDemolition and Construction\nWaste Management Plan\nRevision B Elephants Foot 29 November\n2023\nNoise Impact Assessment P00844\nRevision B\nE-LAB 29 November\n2023\nIntegrated Development - General Terms of Approval\nDocument Title Reference Prepared by Dated\nNSW Rural Fire Services\nLetter of Support\nNSW Rural Fire\nServices\n18 September\n2025\nIn the event of any inconsistency between the approved plans and the supporting\ndocumentation, the approved plans prevail. In the event of any inconsistency between\nthe approved plans and a condition of this consent, the condition prevails.\nNote: Any inconsistency occurs between an approved plan and supporting\ndocumentation or between an approved plan and a condition when it is not possible\nto comply with both at the relevant time.\n1.2 Carry out all building works in accordance with the National Construction Code Series,\nBuilding Code of Australia, Volume 1 and 2 as appropriate.\n1.3 The communal open space is to be landscaped with deep soil and soft ground cover for play\nspaces (equipment), bench seating, shaded areas (such as pergola and the like), and planters for\na community garden. The space should be flexible open space usable in all climates with suitable\nshelters and landscape opportunities. Examples include freestanding structures with solid roofs\nthat offer full protection from sun and rain, often with integrated seating; gazebos which are\npermanent, often octagonal or hexagonal structures with solid roofs, providing a shaded,\ncommunal gathering point; pergolas: Open-roofed structures with cross-beams, providing partial\nshade and a sense of enclosure, often used with climbing plants.\n1.4 Dwellings are to incorporate solar panels on the roof.\n1.5 New street trees are to include banksia and grevilia in addition to tuckeroo to provide\nvisual interest and diversity to the landscape.\n1.6 The built form presentation of the development to Jennings Road should include a variety of\nmaterials, colours and finishes, as well as articulation to break up the façade and provide\nvisual interest and reduce the perceived bulk.\n1.7 A safety rail will be required along the interface between the bin room landing area on the\nfootpath and the driveway to ensure separation between vehicles and the safety of the\npeople transferring bins to and from collection on Jennings Road.\n1.7.1 The footpath will be required to be 2 metres width along the full frontage of the\ndevelopment on Jennings Road, to facilitate adequate space for the storage of bins on\ncollection day and pedestrian thoroughfare.\n1.8 An updated Operational Management Plan (OMP) is to be submitted to the Principal\nCertifying Authority to reflect the recommendations of the conditions contained in this\nconsent.\n1.8.1 The plan is to provide information relating to the management structure of Hume\nCommunity Housing, site maintenance, lighting, noise management, waste management,\nemergency procedures, complaint management procedures, and procedures for the\nperiodical review of the OMP.\n1.8.2 The OMP is to provide clear stakeholder roles and responsibilities to ensure that the\ndevelopment is well managed, and that tenants and management are aware of their rights\nand obligations.\n1.8.3 The Social Impact Assessment recommends the following be factored into the design and\nmanagement plan at the detailed design stage:\n• To maintain good surveillance, it is recommended that landscaping be regularly\nmaintained to ensure existing natural surveillance across the site and to and from the\nstreet is maintained.\n• To ensure good visibility and increase a sense of safety at night, lighting is to be installed:\no at all dwelling entrances and exits;\no at all front gates to the dwellings fronting Jennings Road o along footpaths (foot\nlevel lighting) to front doors for dwellings fronting Jennings Road o on all\nstairwells to front doors o along the driveway (foot level lighting);\no in the car parking areas with lighting installed at a sufficient height to reduce\nthe potential for tampering, and of a design to minimise light spill;\no within the communal open space;\no a sensor light is recommended for the bin area.\n• Bin area to be secured to prevent access by non-residents.\n• A clearly visible street number is to be provided on the site frontage.\n• Signage to be installed to advise that the premises is under 24-hour CCTV surveillance.\n• Clear directional signage to be included to indicate where different dwellings are\nlocated within the site, and to indicate the location of the garbage bins.\n• Each dwelling to have a visible number on the front of the dwelling.\n• The proposed space management practices suggested to be implemented at the\nproposed development include:\no regular maintenance of the premises, including cleaning up of litter or\nrubbish from the car parking areas and grounds;\no regular waste removal;\no rapid removal of any graffiti that may be undertaken on the site;\no regular checks of and rapid repairs to lighting and signage and any damage\non the site.\n• Individual letterboxes should be lockable to impeded unauthorised access.\n2.1. All conditions under this section must be met prior to the issue of any Construction Certificate.\n2.2. Submit an application to Council under section 305 of the Water Management Act 2000 for\na section 306 Requirements Letter. The Application form can be found on Council’s website\ncentralcoast.nsw.gov.au. Early application is recommended.\nThe section 305 application will result in a section 306 letter of requirements which\nmust be obtained prior to the issue of any Construction Certificate. The requirements\n2.PRIOR TO ISSUE OF ANY CONSTRUCTION CERTIFICATE\nletter will outline which requirements must be met prior to each development\nmilestone e.g. prior to construction certificate, subdivision works certificate,\noccupation certificate and/or subdivision certificate.\n2.3. Obtain a Roads Act Works Approval by submitting an application to Council for a Section 138\nRoads Act Works Approval for all works required within the road reserve. The application is to\nbe lodged using an Application for Subdivision Works Certificate or Construction Certificate,\nRoads Act Works Approval and other Development related Civil Works form.\nThe application is to be accompanied by detailed design drawings, reports and other\ndocumentation prepared by a suitably experienced qualified professional in accordance\nwith Council’s Civil Works Specifications.\nFees, in accordance with Council’s Fees and Charges, will be invoiced to the applicant\nfollowing lodgement of the application. Fees must be paid prior to Council\ncommencing assessment of the application.\nDesign drawings, reports and documentation will be required to address the following\nworks within the road reserve:\na) Construction of a residential vehicle access crossing that has a minimum width of 11\nmetres at the road gutter crossing and minimum width of 5.5 metres at the property\nboundary, including construction of a heavy-duty gutter crossing and road pavement\nadjacent to the gutter crossing.\nb) Up to half width road construction including kerb and guttering, subsurface pavement\ndrainage, verge formation, with end transitions across the full frontage of the site in 12-\n14 Jennings Road with a minimum longitudinal length of 42 metres.\nc) Construction of a concrete shared pathway 2 metres wide, including any end treatments\nor road crossing treatments, for the full street frontage of the development in 12-14\nJennings Road with a minimum longitudinal length of 42 metres.\nd) Construction of the road verge/footway formation graded upwards from the top of new\nkerb to the property boundary, across the full frontage of the site in in 12-14 Jennings\nRoad for a minimum length of 42 metres. Construction to include transitions to existing\nformation either side of the site.\ne) Removal of all redundant vehicular access crossings.\nf) Construction of any works required to transition new works into existing infrastructure\nand the surrounding land formation.\ng) Construction of a storm water drainage connection from the development site to\nCouncil’s storm water drainage system within the road reserve generally in accordance\nwith the information presented on Civil Engineering Plans version E, by Tonkin,\n26/03/2025.\nh) Road pavement designs. An Investigation and Design report prepared by a\npractising Geotechnical Engineer must be provided. The pavement design\nthickness must be\ndetermined in accordance with Council’s specifications and the following traffic loadings:\na. Name of Street Traffic Loading (ESAs)\nb. Jennings Road 2 x 10^6\ni) The design is to be certified by a registered practising Civil or Structural engineer as being in\naccordance with Australian Standards.\nj) The section 138 Roads Act Works Approval must be issued by Council and all conditions of\nthat approval must be addressed prior to occupying and commencing any works in the\nroad reserve.\n2.4. Submit to Council a dilapidation report detailing the condition of all Council assets within\nthe vicinity of the development. The report must document and provide photographs that\nclearly depict any existing damage to the road, kerb, gutter, footpath, driveways, street\ntrees, street signs, street lights or any other Council assets in the vicinity of the\ndevelopment.\na) The dilapidation report will be required to be submitted to Council prior to the issue of\nthe Section 138 Roads Act Works approval or the issue of any construction certificate\nfor works on the site. The dilapidation report may be updated with the approval of\nCouncil prior to the commencement of works. The report will be used by Council to\nestablish\ndamage to Council’s assets resulting from the development works.\n2.5. Obtain a Section 68 Local Government Act Works Approval for Stormwater Drainage works\nby submitting an application to Council for a ‘Section 68 Local Government Act Works\nApproval - stormwater drainage’ for storm water drainage works connecting to or within\nCouncil’s storm water system using an Application for Subdivision Works Certificate or\nConstruction Certificate, Roads Act Works Approval and other Development related Civil\nWorks form.\nThe application is to be accompanied by detailed design drawings, reports and other\ndocumentation prepared by a suitably experienced qualified professional in accordance\nwith Council’s Civil Works Specifications.\nFees, in accordance with Council’s Fees and Charges, will be invoiced to the applicant\nfollowing lodgement of the application. Fees must be paid prior to Council commencing\nassessment of the application.\nDesign drawings, reports and documentation will be required to address the\nfollowing works:\na) Construction the connection of all piped and collected stormwater runoff from within the\ndevelopment site to Council’s stormwater system located in Jennings Road.\nb) Construction of stormwater drainage system required to be generally in accordance\nwith the details shown in the Civil Engineering Drawings version E, by Tonkin,\n26/03/2025.\nThe Section 68 Local Government Act Works Approval - stormwater drainage must be issued and all\nconditions of that approval addressed prior to commencing any works that are the subject of the\napproval.\n2.6. Submit to the Registered Certifier responsible for issuing the construction certificate for\nworks within the development site detailed design drawings and design reports for the\nfollowing engineering works:\na) Construction of driveways, ramps and car parking areas in accordance with the\nrequirements of the current edition Australian Standard AS/NZS 2890: Parking\nFacilities and other applicable Australian Standards.\nb) Minimum driveway width of 5.5 metres at the property boundary for a minimum length\nof 6 metres into the site.\nc) Vehicle regulatory signage to be included at the entry and through the\ndevelopment restricting vehicle access to the site to vehicles 6 metres length and\nunder.\nd) Construction of a stormwater drainage retention, detention and pollution control\nmeasures generally in accordance with the details shown in Civil Engineering Drawings\nversion E, by Tonkin, 26/03/2025, including connection into Councils storm water\ndrainage system in Jennings Road. A nutrient and pollution control report including an\noperation and maintenance plan must accompany the design.\ne) Construction of buildings with the minimum floor level of all habitable rooms in\nthe development being Reduced Level (RL) 9.90 m Australian Height Datum\n(AHD).\nf) Bin storage areas to include maximum grade of 3%.\ng) Inclusion of a safety rail between the walkway and the driveway at the bin room landing\narea to ensure no interaction between vehicles and people transferring bins to and from\nJennings Road for collection.\nh) Design of footings for structures, structures and retaining walls to be designed in\naccordance with the requirements of Council’s Guidelines for Building Adjacent to a\nDrainage Easement and Building in Proximity to Water and Sewer Pipelines procedure.\ni) Any retaining walls supporting excavation or fill across the site are to be wholly\nlocated within the site and include a 60 year design life.\nj) Retaining wall design must not conflict with existing or proposed services or utilities.\nRetaining walls designs for wall greater than 600mm in height must be certified by a\nregistered practising Civil or Structural engineer as being in accordance with\nAustralian Standards.\nDetailed design drawings and design reports acceptable to the Registered Certifier must\nbe included in the Construction Certificate documentation.\n2.7. Submit an application to Council under section 305 of the Water Management Act 2000 for\na section 306 Requirements Letter. The Application form can be found on Council’s website\ncentralcoast.nsw.gov.au. Early application is recommended.\nThe section 305 application will result in a section 306 letter of requirements which\nmust be obtained prior to the issue of any Construction Certificate. The requirements\nletter will outline which requirements must be met prior to each development\nmilestone e.g. prior to construction certificate, subdivision works certificate,\noccupation certificate and/or subdivision certificate.\n2.8. Submit to the Registered Certifier, responsible for issuing a construction certificate for works\nwithin the development properties, a carpark, access, and traffic facilities certificate of\ncompliance approved by a suitably qualified traffic professional, demonstrating compliance\nwith design plans, relevant Australian Stands, relevant parts of Councils DCP and Council\nStandard Drawings as applicable.\n2.9. Provide a revised Landscape Plan for Councils Ecologist approval. The landscape plan is to be\nrevised to offset the impacts to the identified threatened entities proposed to be removed.\nSyzygium paniculatum (Mangenta Lilly Pilly) is to replace Cupaniopsis anacardioides\n(Tuckeroo) individuals located in the centre of the proposed development.\n2.10 Contributions Section 7.11\nBefore the issue of a Construction Certificate, pursuant to Section 7.11 of the\nEnvironmental Planning & Assessment Act, the applicant must pay contributions to\nCouncil totalling $135,912.50 as calculated at the date of this consent, in accordance\nwith the Wyong District Section 7.11 Plan 2020. Refer to table below for full itemised\nlist of contributions levied under this condition.\nThe total amount payable may be adjusted at the time the payment is made, in\naccordance with the provisions of the Wyong District Section 7.11 Plan 2020.\nContributions under the Wyong District Section 7.11 Plan 2020 are subject to\nquarterly indexation by CPI.\nA copy of the Contributions Plan is available for inspection at 2 Hely St, Wyong or on\nCouncil's website: Development Contributions Plans and Planning Agreements | Central\nCoast Council (nsw.gov.au)\n3.1. All conditions under this section must be met prior to the commencement of any works.\n3.2. Ensure that all parties / trades working on the site are fully aware of their responsibilities\nwith respect to tree protection conditions.\n3.3. Protective fencing\na) Fencing is to be erected before any machinery or materials are brought onto the site and\nbefore commencement of works. Once erected, protective fencing must not be removed\nor altered with.\nb) Erect a barrier fence between works and trees to be retained, no closer than two metres\nfrom tree trunk. Radius is measured from the centre of the stem at ground level and to be\nconstructed of 1.8-meter-high temporary chain wire fencing.\nc) Sign-post fences around Tree Protection Zones to warn of its purpose.\n3.4. Prepare a Construction Traffic and Pedestrian Management Plan (CTPMP) for all activities\nrelated to works within the site. The plan must be prepared and implemented only by persons\nwith Roads and Maritime Service accreditation for preparing and implementing traffic\nmanagement plans at work sites.\nThe CTPMP must describe the proposed construction works, the traffic impacts on the\nlocal area and how these impacts will be addressed.\nThe CTPMP must address, but not be limited to, the following matters:\na) Ingress and egress of construction related vehicles to the development site.\nb) Details of the various vehicle lengths that will be used during construction and the\nfrequency of these movement.\nc) Use of swept path diagrams to demonstrate how heavy vehicles enter, circulate and exit\nthe site or Works Zone in a forward direction.\nd) Deliveries to the site, including loading / unloading materials and requirements for work\nzones along the road frontage to the development site. A Plan is to be included that shows\nwhere vehicles stand to load and unload, where construction plant will stand, location of\nstorage areas for equipment, materials and waste, locations of Work Zones (if required) and\nlocation of cranes (if required).\ne) Works Zones if heavy vehicles cannot enter or exit the site in a forward direction.\nf) Control of pedestrian and vehicular traffic where pre-construction routes are affected.\n3.PRIOR TO COMMENCEMENT OF ANY WORKS\ng) Temporary Road Closures.\nWhere the plan identifies that the travel paths of pedestrians and vehicular traffic are\nproposed to be interrupted or diverted for any construction activity related to works\ninside the development site an application must be made to Council for a Road\nOccupancy Licence.\nImplementation of traffic management plans that address interruption or diversion of\npedestrian and/or vehicular traffic must only take place following receipt of a Road\nOccupancy Licence from Council or the Roads and Maritime Service where on a\nclassified road.\nWhere a dedicated delivery vehicle loading and unloading zone is required along the\nroad frontage of the development site a Works Zone Application must be lodged and\napproved by Council. A minimum of 3 months is required to allow Traffic Committee\nendorsement and Council approval.\nThe Construction Traffic and Pedestrian Management Plan must be reviewed and\nupdated during construction of the development to address any changing site\nconditions.\nA copy of the Construction Traffic and Pedestrian Management Plan must be held on\nsite at all times and be made available to Council upon request.\n3.5. Submit to Council a completed Notice of Intention to Commence Subdivision, Roads and\nStormwater Drainage Works form with supporting documentation prior to the\ncommencement of any Subdivision Works Certificate works, Roads Act Works Approval\nworks, or Section 68 Local Government Act Stormwater Drainage Works Approval works.\nThese works are not to commence until a pre-commencement site meeting has been held\nwith Council.\n3.6. Submit a Hoarding Application to Council for approval under the Roads Act where it is\nproposed to erect construction fencing, a hoarding, site sheds or utilise the road reserve for\nany construction activity related to the development works within the site.\nFees, in accordance with Council’s Fees and Charges, will be invoiced to the applicant\nfollowing lodgement of the application and will be required to be paid prior to Council\nreleasing any approval.\n3.7 No activity is to be carried out on-site until the Construction Certificate has been issued,\nother than:\na) Site investigation for the preparation of the construction, and / or\nb) Implementation of environmental protection measures, such as erosion control and\nthe like that are required by this consent.\nc) Any demolition approved by this consent.\n3.8 Appoint a Principal Certifying Authority for the building work:\na) The Principal Certifying Authority (if not Council) is to notify Council of their appointment\nand notify the person having the benefit of the development consent of any critical stage\ninspections and other inspections that are to be carried out in respect of the building work\nno later than two (2) days before the building work commences.\nb) Submit to Council a Notice of Commencement of Building Works or Notice of Commencement\nof Subdivision Works form giving at least two (2) days’ notice of the intention to\ncommence\nbuilding or subdivision work. The forms can be found on Council’s website:\nwww.centralcoast.nsw.gov.au\n3.9 Erect a sign in a prominent position on any work site on which building, subdivision or demolition\nwork is being carried out. The sign must indicate:\na) The name, address and telephone number of the Principal Certifying Authority for the\nwork; and\nb) The name of the principal contractor and a telephone number at which that person can\nbe contacted outside of working hours; and\nc) That unauthorised entry to the work site is prohibited.\nd) Remove the sign when the work has been completed. (GL011)\n3.10 Install run-off and erosion controls to prevent soil erosion, water pollution or the discharge\nof loose sediment on the surrounding land by:\n• erecting a silt fence and providing any other necessary sediment control measures that\nwill prevent debris escaping into drainage systems, waterways or adjoining properties,\nand\n• diverting uncontaminated run-off around cleared or disturbed areas, and\n• preventing the tracking of sediment by vehicles onto roads, and\n• stockpiling top soil, excavated materials, construction and landscaping supplies and\ndebris within the lot.\n3.11 Prior to commencement of construction or site works, a Soil and Water Management Plan\n(SWMP) prepared in accordance with the latest edition of the Landcom Publication “Managing\nUrban Stormwater: Soils and Construction - Volume 1” (the Blue Book). Sediment control\nfencing must remain in place until such time as the site is landscaped or turf is established.\nNote: Discharge of sediment from a site may be determined to be a pollution event under\nprovisions of the Protection of the Environment Operations Act 1997. Enforcement action may\ncommence where sediment movement produces a pollution event.\n3.12 Provide or make available toilet facilities at the work site before works begin and maintain the\nfacilities until the works are completed at a ratio of one toilet plus one additional toilet for\nevery twenty (20) persons employed at the site.\nEach toilet must:\na) be a standard flushing toilet connected to a public sewer, or\nb) have an on-site effluent disposal system approved under the Local Government Act 1993, or\nc) be a temporary chemical closet approved under the Local Government Act 1993.\n4.1. All conditions under this section must be met during works.\n4.2. Tree Removal\nTrees to be removed to accommodate for the development as specified in the Arborist\nReport by Tattersall Lander in September 2023.\n4.3. Manual (hand) excavation must occur when within three metres of trees to be retained.\nAll care is to be taken to avoid damage to tree roots.\nRoots that can’t be avoided are to be cut (not ripped) with a sharp tool such as pruners or\nhandsaw.\nSeek Arboricultural advice before severing roots greater than 75mm diameter.\n4.4. Activities generally excluded from the Tree Protection Zone, but not limited to:\na) Machine excavation, trenching, material storage, prepare chemicals or cement,\npark, refuel, dump waste, wash down, fill or change soil level.\n4.5. Re-use, recycle or dispose of all building materials in accordance with the Waste\nManagement Plan submitted with the subject application.\n4.6. Re-use, recycle or dispose of all building materials in accordance with the Waste\nManagement Plan submitted with the subject application.\n4.7. Undertake clearing in accordance with the approved tree removal/retention survey plan.\nTrees must be removed in such a manner so as to prevent damage to surrounding trees to\nbe retained.\n4.8. Supply any plant stock used in landscaping from provenance specific seed/material collected\nfrom locally endemic species to maintain genetic diversity. Plant stock should be sourced\nfrom local nurseries to Wyong. Non-provenance specific material is prohibited.\n4.9 No activity is to be carried out on-site until the Construction Certificate has been issued,\n4.DURING WORKS\nother than:\n• Site investigation for the preparation of the construction, and / or\n• Implementation of environmental protection measures, such as erosion control and\nthe like that are required by this consent.\n• Any demolition approved by this consent.\n4.10 Appoint a Principal Certifying Authority for the building work:\n• The Principal Certifying Authority (if not Council) is to notify Council of their appointment\nand notify the person having the benefit of the development consent of any critical stage\ninspections and other inspections that are to be carried out in respect of the building\nwork no later than two (2) days before the building work commences.\n• Submit to Council a Notice of Commencement of Building Works or Notice of\nCommencement of Subdivision Works form giving at least two (2) days’ notice of the\nintention to commence building or subdivision work. The forms can be found on\nCouncil’s\nwebsite: www.centralcoast.nsw.gov.au\n4.11 Erect a sign in a prominent position on any work site on which building, subdivision\nor demolition work is being carried out. The sign must indicate:\n• The name, address and telephone number of the Principal Certifying Authority for\nthe work; and\n• The name of the principal contractor and a telephone number at which that person can\nbe contacted outside of working hours; and\n• That unauthorised entry to the work site is prohibited.\n• Remove the sign when the work has been completed.\n4.12 Install run-off and erosion controls to prevent soil erosion, water pollution or the discharge\nof loose sediment on the surrounding land by:\no erecting a silt fence and providing any other necessary sediment control\nmeasures that will prevent debris escaping into drainage systems, waterways or\nadjoining properties, and\no diverting uncontaminated run-off around cleared or disturbed areas, and\no preventing the tracking of sediment by vehicles onto roads, and\no stockpiling top soil, excavated materials, construction and landscaping supplies\nand debris within the lot.\n4.13 Prior to commencement of construction or site works, a Soil and Water Management\nPlan (SWMP) prepared in accordance with the latest edition of the Landcom Publication\n“Managing Urban Stormwater: Soils and Construction - Volume 1” (the Blue Book).\nSediment control fencing must remain in place until such time as the site is\nlandscaped or turf is established.\nNote: Discharge of sediment from a site may be determined to be a pollution event under\nprovisions of the Protection of the Environment Operations Act 1997. Enforcement action\nmay commence where sediment movement produces a pollution event.\n4.14 Provide or make available toilet facilities at the work site before works begin and maintain\nthe facilities until the works are completed at a ratio of one toilet plus one additional toilet\nfor every twenty (20) persons employed at the site.\nEach toilet must:\no be a standard flushing toilet connected to a public sewer, or\no have an on-site effluent disposal system approved under the Local Government\nAct 1993, or\no be a temporary chemical closet approved under the Local Government Act 1993.\n4.15 The principal certifier must ensure that building work, demolition or vegetation removal\nis only carried out between:\n7.00 am and 5.00 pm on Monday to Saturday\nThe principal certifier must ensure building work, demolition or vegetation removal is\nnot carried out on Sundays or a public holidays, except where there is an emergency.\nUnless otherwise approved within a construction site management plan, construction\nvehicles, machinery, goods or materials must not be delivered to the site outside the\napproved hours of site works.\nNote: Any variation to the hours of work requires Council’s approval. GL014\n4.16 Use of High Noise emission appliances and plant\nThe operation of high noise emission appliances, plant and/or machinery such as pile -\ndrivers, rock breakers and hydraulic hammers\n• Monday to Friday - 9:00am to 12:30pm and 2:00pm to 4:30pm\n• Saturday - 9:00am to 1:00pm\n• Sunday and Public Holidays - No works permitted\nAll reasonable and feasible steps must be undertaken to ensure that the work,\nincluding demolition, excavation and building complies with The Interim Construction\nNoise Guideline in NSW and Australian Standard 2436- 2010 Guide to Noise Control\non Construction, Maintenance and Demolition Sites.\n4.17 While demolition or building work is being carried out, all such works must cease\nimmediately if a relic or Aboriginal object is unexpectedly discovered. The applicant must\nnotify the Heritage Council of NSW in respect of a relic and notify the Secretary of the\nDepartment of Planning, Industry and Environment and the Heritage Council of NSW in\nrespect of an Aboriginal object. Building work may recommence at a time confirmed by\neither the Heritage Council of NSW or the Secretary of the Department of Planning, Industry\nand Environment.\nIn this condition:\n“relic” means any deposit, artefact, object or material evidence that:\n(a) relates to the settlement of the area that comprises New South Wales, not\nbeing Aboriginal settlement, and\n(b) is of State or local heritage significance; and\n“Aboriginal object” means any deposit, object or material evidence (not being a\nhandicraft made for sale) relating to the Aboriginal habitation of the area that\ncomprises New South Wales, being habitation before or concurrent with (or both) the\noccupation of that area by\npersons of non-Aboriginal extraction and includes Aboriginal remains. To ensure the\nprotection of objects of potential sign GL015\n4.18 Implement and maintain all erosion and sediment control measures at or above design\ncapacity for the duration of the construction works and until such time as all ground\ndisturbed by the works has been stabilised and rehabilitated so that it no longer acts as\na source of sediment. (GL016)\n4.19 Keep a copy of the stamped approved plans on-site for the duration of site works and\nmake the plans available upon request to either the Principal Certifying Authority or an\nofficer of Council. (GL017)\n4.20 Provide and maintain a garbage receptacle at the work site until the works are\ncompleted. The garbage receptacle must have a tight fitting lid and be suitable for food\nscraps and papers.\n4.21 Place all building materials, plant and equipment on the site of the development during the\nconstruction phase of the development so as to ensure that pedestrian and vehicular access\nwithin adjoining public roads, footpaths and reserve areas, is not restricted and to prevent\ndamage to public infrastructure. Further, no construction work is permitted to be carried\nout within the road reserve unless the works are associated with a separate approval issued\nunder the provisions of the Roads Act 1993.\n4.22 While building work is being carried out and where no noise and vibration management\nplan is approved under this consent, the applicant is to ensure that any noise caused by\ndemolition, vegetation removal or construction does not exceed an LAeq (15 min) of 5dB(A)\nabove background noise, when measured at any lot boundary of the property where the\nconstruction is being carried out.\n4.23 Demolish all buildings and / or building components in a safe and systematic manner in\naccordance with Australian Standard AS 2601-2001: The demolition of structures.\nWaste materials must be disposed of at a waste management facility.\n4.24 Undertake any demolition involving asbestos in accordance with the Work Health and\nSafety Act 2011.\nThe person having the benefit of this consent must ensure that the removal of:\na) more than 10m2 of non-friable asbestos or asbestos containing material is carried out\nby a licensed non-friable (Class B) or a friable (Class A) asbestos removalist, and\nb) friable asbestos of any quantity is removed by a licensed removalist with a friable\n(Class A) asbestos removal licence\nThe licensed asbestos removalist must give notice to the regulator before work\ncommences in accordance with Clause 466 of the Work Health and Safety Regulation\n2011.\n4.25 Disconnect, seal and make safe all existing site services prior to the commencement of any\ndemolition on the site. Sewer and water services must be disconnected by a licensed\nplumber and drainer with a Start Work Docket submitted to Council's Plumbing and\nDrainage Inspector as the Water and Sewer Authority.\n4.26 Immediately notify Council of any new information which comes to light during remediation,\ndemolition or construction works which has the potential to alter previous conclusions about\nsite contamination and remediation.\n5.1. All conditions under this section must be met prior to the issue of any Occupation Certificate.\n5.2. Obtain the Section 307 Certificate of Compliance under the Water Management Act 2000\nfor water and sewer requirements for the development from Central Coast Council as the\nWater Supply Authority, prior to issue of the Occupation Certificate.\n5.3. Implement the following Crime Prevention through Environmental Design (CPTED) principles\nand strategies to minimise the opportunity for crime:\na) provide adequate lighting to common areas as required under Australian Standard AS 1158:\nLighting for roads and public spaces\nb) design of landscaping, adjacent to mailboxes and footpaths, must not provide\nconcealment opportunities for criminal activity\nc) design the development to avoid foot holes or natural ladders so as to minimise\nunlawful access to the premises\nd) provide signage within the development to identify all facilities, entry / exit points and\ndirect movement within the development\n5.PRIOR TO ISSUE OF ANY OCCUPATION CERTIFICATE\ne) install a system of Closed Circuit Television of a type and in locations on the site that\nwill record high-quality images of all public areas within the site.\n5.4. Install a system of Closed Circuit Television (CCTV) of a type and in locations on the site that\nwill provide high-quality images of all public areas within the site.\n5.5. Construct any additional civil works, where required by Council, to ensure satisfactory\ntransitions to existing site formations and pavements where designs contained in the Roads\nAct Works Approval do not adequately address transition works.\n5.6. Complete construction of the stormwater management system in accordance with the Stormwater\nManagement Plan and Australian Standard AS 3500.3-Stormwater drainage systems. Certification\nof the construction by a suitably qualified consultant must be provided to the Principal Certifier.\n5.7. Complete construction of all works within the road reserve in accordance with the Roads Act\nWorks Approval. Completion of works includes the submission and acceptance by Council of\nall work as executed drawings plus other construction compliance documentation and\npayment of a maintenance/defects bond to Council in accordance with Council’s Fees and\nCharges.\n5.8. Repair any damage to Council’s infrastructure and road reserve as agreed with Council.\nDamage not shown in the dilapidation report submitted to Council before the development\nworks had commenced will be assumed to have been caused by the development works\nunless the Developer can prove otherwise.\n5.9. Complete construction of all works approved in the Local Government Act Section 68\nStormwater Drainage Works Approval. Completion include the submission and acceptance by\nCouncil of all work as executed drawings plus other construction compliance documentation\nand payment of a maintenance/defects bond to Council in accordance with Council’s adopted\nfees and charges.\n5.10. Complete the civil engineering works within the development site in accordance with\nthe detailed design drawings and design reports plans within the construction\ncertificate.\n5.11. Amend the Certificate of title for lot 1 DP 1230068 to:\n1) Include an Instrument under the Conveyancing Act 1919 for the following restrictive\ncovenants; with Council having the benefit of these covenants (as applicable) and having sole\nauthority to release and modify. Wherever possible, the extent of land affected by these\ncovenants must be defined by bearings and distances shown on the plan. The plan and\ninstrument must:\n• Create a ‘Restriction on the use of Land’ over all lots containing an on-site stormwater\ndetention and retention system and / or a nutrient / pollution facility restricting any\nalteration to such facility or the erection of any structure over the facility or the\nplacement of any obstruction over the facility.\n2) Include an instrument under the Conveyancing Act 1919 for the following positive\ncovenants; with Council having the benefit of these covenants and having sole authority to\nrelease and modify. Covenant(s) required:\na) To ensure on any lot containing on-site stormwater detention and retention system and\n/ or a nutrient / pollution facility that:\ni. the facility will remain in place and fully operational.\nii. the facility is maintained in accordance with the operational and\nmaintenance plan so that it operates in a safe and efficient manner.\niii. Council’s officers are permitted to enter the land to inspect and repair\nthe facility at the owner’s cost.\niv. Council is indemnified against all claims of compensation caused by the facility.\nNote: Standard wording, acceptable to Council, for covenants can be obtained by\ncontacting Council Subdivision Certificate Officer.\nSubmit to the Principal Certifier copies of registered title documents showing the restrictive\nand positive covenants.\n5.12. Complete Construction of driveways, ramps and car parking areas in accordance with the\nrequirements of the current edition Australian Standard AS/NZS 2890: Parking Facilities, other\napplicable Australian Standards and the detailed designs and design reports within the\nconstruction certificate. Certification by a suitably qualified person that construction is\ncomplete is to be provided to the Principal Certifier.\n5.13 Obtain the Section 307 Certificate of Compliance under the Water Management Act 2000\nfor water and sewer requirements for the development from Central Coast Council as the\nWater Supply Authority, prior to issue of the Occupation Certificate.\n5.14 Complete the building in accordance with the relevant provisions and requirements of\nthe National Construction Code Series.\n5.15 Complete the landscaping works. Provide the Principal Certifier with written certification from\na qualified landscape designer certifying that landscaping has been implemented in\naccordance with the approved landscape plan as amended by any conditions of this consent.\n6.1. Manage any incidences of anti-social behaviour or nuisance on the site by implementing\nappropriate responses to such incidences if they occur. The owner / operator(s) must also\ntake appropriate measures after any such incident to reduce the likelihood of such\nincidences reoccurring on the site.\n6.2. Operate and maintain all external lighting so as not to impact on any adjoining property.\n6.3. Implement and comply with all recommendations in the acoustic report prepared by E-LAB\ndated 29 November 2023.\n6.ONGOING\n6.4. Maintain the installed system of Closed Circuit Television (CCTV) that monitors / records all\npublic areas within the site.\n6.5. Maintain the external finishes of the building(s), structures, walls and fences for the life of\nthe development and remove any graffiti within seven (7) days.\n6.6. All vehicles greater than 6 metres in length are to be restricted from entering the site.\n6.7 Replace all damaged, dead or missing areas of lawn and plantings at the completion of the\nlandscaping maintenance period, including adjoining road reserve areas that are in a state\nof decline, to a healthy and vigorous condition in accordance with the approved detailed\nLandscape Plans and Development Consent Conditions.\n6.8 Place the mobile garbage / recycling / green waste containers at a suitable location at the\nkerbside no earlier than the evening prior to the collection day and return to a screened\narea as soon as possible after service, no later than the evening on collection day. The\nresidents/ owner’s association are responsible for the placement and return of the mobile\nwaste containers.\n6.9 Maintain all works associated with the approved Landscape Plans for the life of\nthe development to ensure the survival and establishment of the landscaping.\n6.10 Maintain the external finishes of the building(s), structures, walls and fences for the life of\nthe development and remove any graffiti within seven (7) days.\n6.11 Maintain internal pavement and pavement marking.\nFailure to comply with this development consent and any condition of this consent may be a\ncriminal offence. Failure to comply with other environmental laws may also be a criminal\noffence.\nWhere there is any breach Council may without any further warning:\n• Issue Penalty Infringement Notices (On-the-spot fines);\n• Issue notices and orders;\n• Prosecute any person breaching this consent, and/or\n• Seek injunctions/orders before the courts to retain and remedy any breach.\nWarnings as to Potential Maximum Penalties\nMaximum Penalties under NSW Environmental Laws include fines up to $1.1 Million and/or\ncustodial sentences for serious offences.\n• Offence to disturb Aboriginal artefact.\n10.PENALTIES","stage":"general","stage_basis":"heading","page":9}]});
